macro_rules! deps {
    () => {
        Expression!();
        Register!();
        Piece!();
        DebugInfoRef!();
        Relocate!();
        Address!();
    };
}

macro_rules! Operation {
    () => {
        deps!();
        # [doc = " A single DWARF operation."] # [derive (Debug , Clone , PartialEq , Eq , Hash)] enum Operation { # [doc = " Raw bytecode."] # [doc = ""] # [doc = " Does not support references."] Raw (Vec < u8 >) , # [doc = " An operation that has no explicit operands."] # [doc = ""] # [doc = " Represents:"] # [doc = " - `DW_OP_drop`, `DW_OP_swap`, `DW_OP_rot`"] # [doc = " - `DW_OP_push_object_address`, `DW_OP_form_tls_address`, `DW_OP_call_frame_cfa`"] # [doc = " - `DW_OP_abs`, `DW_OP_and`, `DW_OP_div`, `DW_OP_minus`, `DW_OP_mod`, `DW_OP_mul`,"] # [doc = "   `DW_OP_neg`, `DW_OP_not`, `DW_OP_or`, `DW_OP_plus`, `DW_OP_shl`, `DW_OP_shr`,"] # [doc = "   `DW_OP_shra`, `DW_OP_xor`"] # [doc = " - `DW_OP_le`, `DW_OP_ge`, `DW_OP_eq`, `DW_OP_lt`, `DW_OP_gt`, `DW_OP_ne`"] # [doc = " - `DW_OP_nop`"] # [doc = " - `DW_OP_stack_value`"] Simple (DwOp) , # [doc = " Relocate the address if needed, and push it on the stack."] # [doc = ""] # [doc = " Represents `DW_OP_addr`."] Address (Address) , # [doc = " Push an unsigned constant value on the stack."] # [doc = ""] # [doc = " Represents `DW_OP_constu`."] UnsignedConstant (u64) , # [doc = " Push a signed constant value on the stack."] # [doc = ""] # [doc = " Represents `DW_OP_consts`."] SignedConstant (i64) , # [doc = " Interpret the value bytes as a constant of a given type, and push it on the stack."] # [doc = ""] # [doc = " Represents `DW_OP_const_type`."] ConstantType (UnitEntryId , Box < [u8] >) , # [doc = " Compute the frame base (using `DW_AT_frame_base`), add the"] # [doc = " given offset, and then push the resulting sum on the stack."] # [doc = ""] # [doc = " Represents `DW_OP_fbreg`."] FrameOffset (i64) , # [doc = " Find the contents of the given register, add the offset, and then"] # [doc = " push the resulting sum on the stack."] # [doc = ""] # [doc = " Represents `DW_OP_bregx`."] RegisterOffset (Register , i64) , # [doc = " Interpret the contents of the given register as a value of the given type,"] # [doc = " and push it on the stack."] # [doc = ""] # [doc = " Represents `DW_OP_regval_type`."] RegisterType (Register , UnitEntryId) , # [doc = " Copy the item at a stack index and push it on top of the stack."] # [doc = ""] # [doc = " Represents `DW_OP_pick`, `DW_OP_dup`, and `DW_OP_over`."] Pick (u8) , # [doc = " Pop the topmost value of the stack, dereference it, and push the"] # [doc = " resulting value."] # [doc = ""] # [doc = " Represents `DW_OP_deref` and `DW_OP_xderef`."] Deref { # [doc = " True if the dereference operation takes an address space"] # [doc = " argument from the stack; false otherwise."] space : bool , } , # [doc = " Pop the topmost value of the stack, dereference it to obtain a value"] # [doc = " of the given size, and push the resulting value."] # [doc = ""] # [doc = " Represents `DW_OP_deref_size` and `DW_OP_xderef_size`."] DerefSize { # [doc = " True if the dereference operation takes an address space"] # [doc = " argument from the stack; false otherwise."] space : bool , # [doc = " The size of the data to dereference."] size : u8 , } , # [doc = " Pop the topmost value of the stack, dereference it to obtain a value"] # [doc = " of the given type, and push the resulting value."] # [doc = ""] # [doc = " Represents `DW_OP_deref_type` and `DW_OP_xderef_type`."] DerefType { # [doc = " True if the dereference operation takes an address space"] # [doc = " argument from the stack; false otherwise."] space : bool , # [doc = " The size of the data to dereference."] size : u8 , # [doc = " The DIE of the base type, or `None` for the generic type."] base : UnitEntryId , } , # [doc = " Add an unsigned constant to the topmost value on the stack."] # [doc = ""] # [doc = " Represents `DW_OP_plus_uconst`."] PlusConstant (u64) , # [doc = " Unconditional branch to the target location."] # [doc = ""] # [doc = " The value is the index within the expression of the operation to branch to."] # [doc = " This will be converted to a relative offset when writing."] # [doc = ""] # [doc = " Represents `DW_OP_skip`."] Skip (usize) , # [doc = " Branch to the target location if the top of stack is nonzero."] # [doc = ""] # [doc = " The value is the index within the expression of the operation to branch to."] # [doc = " This will be converted to a relative offset when writing."] # [doc = ""] # [doc = " Represents `DW_OP_bra`."] Branch (usize) , # [doc = " Evaluate a DWARF expression as a subroutine."] # [doc = ""] # [doc = " The expression comes from the `DW_AT_location` attribute of the indicated DIE."] # [doc = ""] # [doc = " Represents `DW_OP_call4`."] Call (UnitEntryId) , # [doc = " Evaluate an external DWARF expression as a subroutine."] # [doc = ""] # [doc = " The expression comes from the `DW_AT_location` attribute of the indicated DIE,"] # [doc = " which may be in another compilation unit or shared object."] # [doc = ""] # [doc = " Represents `DW_OP_call_ref`."] CallRef (DebugInfoRef) , # [doc = " Compute the value of a variable and push it on the stack."] # [doc = ""] # [doc = " Represents `DW_OP_GNU_variable_value`."] VariableValue (DebugInfoRef) , # [doc = " Pop the top stack entry, convert it to a different type, and push it on the stack."] # [doc = ""] # [doc = " Represents `DW_OP_convert`."] Convert (Option < UnitEntryId >) , # [doc = " Pop the top stack entry, reinterpret the bits in its value as a different type,"] # [doc = " and push it on the stack."] # [doc = ""] # [doc = " Represents `DW_OP_reinterpret`."] Reinterpret (Option < UnitEntryId >) , # [doc = " Evaluate an expression at the entry to the current subprogram, and push it on the stack."] # [doc = ""] # [doc = " Represents `DW_OP_entry_value`."] EntryValue (Expression) , # [doc = " Indicate that this piece's location is in the given register."] # [doc = ""] # [doc = " Completes the piece or expression."] # [doc = ""] # [doc = " Represents `DW_OP_regx`."] Register (Register) , # [doc = " The object has no location, but has a known constant value."] # [doc = ""] # [doc = " Completes the piece or expression."] # [doc = ""] # [doc = " Represents `DW_OP_implicit_value`."] ImplicitValue (Box < [u8] >) , # [doc = " The object is a pointer to a value which has no actual location, such as"] # [doc = " an implicit value or a stack value."] # [doc = ""] # [doc = " Completes the piece or expression."] # [doc = ""] # [doc = " Represents `DW_OP_implicit_pointer`."] ImplicitPointer { # [doc = " The DIE of the value that this is an implicit pointer into."] entry : DebugInfoRef , # [doc = " The byte offset into the value that the implicit pointer points to."] byte_offset : i64 , } , # [doc = " Terminate a piece."] # [doc = ""] # [doc = " Represents `DW_OP_piece`."] Piece { # [doc = " The size of this piece in bytes."] size_in_bytes : u64 , } , # [doc = " Terminate a piece with a size in bits."] # [doc = ""] # [doc = " Represents `DW_OP_bit_piece`."] BitPiece { # [doc = " The size of this piece in bits."] size_in_bits : u64 , # [doc = " The bit offset of this piece."] bit_offset : u64 , } , # [doc = " This represents a parameter that was optimized out."] # [doc = ""] # [doc = " The entry is the definition of the parameter, and is matched to"] # [doc = " the `DW_TAG_GNU_call_site_parameter` in the caller that also"] # [doc = " points to the same definition of the parameter."] # [doc = ""] # [doc = " Represents `DW_OP_GNU_parameter_ref`."] ParameterRef (UnitEntryId) , # [doc = " The index of a local in the currently executing function."] # [doc = ""] # [doc = " Represents `DW_OP_WASM_location 0x00`."] WasmLocal (u32) , # [doc = " The index of a global."] # [doc = ""] # [doc = " Represents `DW_OP_WASM_location 0x01`."] WasmGlobal (u32) , # [doc = " The index of an item on the operand stack."] # [doc = ""] # [doc = " Represents `DW_OP_WASM_location 0x02`."] WasmStack (u32) , }
    };
}

Operation!();